// Access the first item from the input
const item = items[0].json;

// Ensure html_content exists
if (!item.html_content) {
  throw new Error("No html_content found in the input data.");
}

const text = item.html_content;
const buffer = Buffer.from(text, 'utf8');

// Construct the binary object
const binaryData = {
  data: buffer.toString('base64'),
  mimeType: 'text/html', // Changed to text/html for better compatibility
  fileName: 'literature_review.html',
};

// Assign the binary data to the current item
items[0].binary = { data: binaryData };

return items;
